import path from 'node:path';
import assert from 'node:assert/strict';
import {buildCatalogue} from './bedrock/tools/catalogue.mjs';
import {loadLockedRuntime,reconcileCatalogue} from './bedrock/tools/runtime-reconciliation.mjs';
const workspace=path.resolve('bedrock');
const catalogue=await buildCatalogue(path.join(workspace,'.work/java-reference/source'));
const {runtime,lock}=await loadLockedRuntime(workspace);
const id='betterend:thallasium/repair';
runtime.registryTags['minecraft:item']=runtime.registryTags['minecraft:item'].filter(tag=>tag.id!==id);
const reconciled=reconcileCatalogue(catalogue,runtime,lock);
const diagnostic=reconciled.reconciliation.tagBindingIssues.find(issue=>issue.id===id);
assert.equal(diagnostic?.code,'missing-runtime-tag');
assert.equal(reconciled.resources.find(row=>row.category==='tags/item' && row.id===id).runtimeResource.matchesSourceBytes,true);
assert.ok(reconciled.unresolved.some(issue=>issue.code==='missing-runtime-tag-bindings' && issue.severity==='release-blocker'));
console.log(JSON.stringify({scope:'in-memory omission from the actual locked corpus; original evidence unchanged',rawResourceStillMatches:true,diagnostic,releaseBlocked:true},null,2));

